// Frozen presentation functions from a38faaf; test-only, excluded from runtime.
module.exports={"functions": {"filterBySearch": "    function filterBySearch(carList, query) {\n        if (!query) return [...carList];\n        const q = query.toLowerCase();\n        return carList.filter(car => {\n            if (car.includes(query)) return true;\n            if (nickToName[car] && nickToName[car].toLowerCase().includes(q)) return true;\n            // 别名匹配：查所有指向此车的别名键\n            for (var aliasKey in NICKNAME_ALIASES) {\n                if (NICKNAME_ALIASES[aliasKey] === car && aliasKey.includes(query)) return true;\n            }\n            return false;\n        });\n    }", "filterByClass": "    function filterByClass(carList, cls) {\n        if (!cls) return [...carList];\n        return carList.filter(car => {\n            const stats = carStats[nickToName[car]];\n            return stats && stats.class === cls;\n        });\n    }", "sortCarList": "    function sortCarList(carList, mode) {\n        const sorted = [...carList];\n        if (mode === 'score-desc' || mode === 'score-asc') {\n            sorted.sort((a, b) => {\n                const left = carStats[nickToName[a]]?.score, right = carStats[nickToName[b]]?.score;\n                const leftKnown = Number.isFinite(left), rightKnown = Number.isFinite(right);\n                if (leftKnown !== rightKnown) return leftKnown ? -1 : 1;\n                if (!leftKnown) return a.localeCompare(b, 'zh');\n                return mode === 'score-desc' ? right - left : left - right;\n            });\n        } else {\n            sorted.sort((a, b) => a.localeCompare(b, 'zh'));\n        }\n        return sorted;\n    }", "getTopCars": "    function getTopCars(candidate, ownedInZone, big, small, zone) {\n        const cars = [...new Set(candidate.groups.flat())].filter(car => ownedInZone.has(car)).slice(0, 3);\n        return cars.map(car => ({\n            car,\n            stars: currentTier === '理论' ? null : getCarStars(car),\n            score: getCarScore(big, small, car, zone),\n        }));\n    }", "updateSubtitle": "    function updateSubtitle() {\n        if (APP_CONFIG.server === 'global') { const sub = document.querySelector('.sub'); if (sub) sub.textContent = '国际服 · 五区满星理论参考 · 含特殊跑法'; return; }\n        const tierInfo = RACE_DATA?.tier_info?.[currentTier];\n        const sub = document.querySelector('.sub');\n        if (sub && tierInfo) {\n            let desc = tierInfo.desc;\n            // 理论档在四区模式下显示不同描述\n            if (currentTier === '理论' && currentZone === 'zone4') {\n                desc = '顶级特改理论成绩，默认最优解，含特殊跑法';\n            }\n            sub.textContent = desc;\n        }\n    }"}, "aliases": "{\n        '第六元素': '六子',\n        '兔子': 'c2',\n    }"};
